NAME = 'GerLeoNA28: Leonberger Bibel, NT (NA28)'
BOOK = 'I Timothy'

CHAPTERS = {
    1: {
        1: 'Paulus, ein Apostel von Christus Jesus im Auftrag Gottes, unseres Retters, und von Christus Jesus, unserer Hoffnung. /',
        2: 'An Timotheus, einem echten Kind im Glauben: /Gnade, Barmherzigkeit, Frieden von Gott dem Vater und von Christus Jesus, unserem Herrn!',
        3: 'Wie ich dich aufgefordert hatte, in Ephesus zu bleiben, während ich nach Makedonia reiste, damit du gewissen [Leuten] gebietest, nichts anderes zu lehren',
        4: 'und sich nicht Legenden und endlosen Ahnentafeln zu widmen, die mehr zu Streitfragen beitragen als zum Plan Gottes, der im Glauben [verwirklicht wird].',
        5: 'Das Ziel der Anweisung aber ist Liebe aus reinem Herzen und gutem Gewissen und ungeheucheltem Glauben,',
        6: 'wovon einige abgewichen sind und sich zu leerem Geschwätz haben ablenken lassen,',
        7: 'weil sie Gesetzeslehrer sein wollen, obwohl sie nichts verstehen – weder was sie sagen noch worüber sie Behauptungen aufstellen.',
        8: 'Wir wissen aber, dass das Gesetz gut [ist], wenn jemand es dem Gesetz entsprechend gebraucht,',
        9: 'indem er Folgendes beherzigt: Das Gesetz wird nicht dem Gerechten gegeben, sondern den Gesetzlosen und Rebellischen, den Gottlosen und Sündern, den Unheiligen und Verweltlichten, den Vatermörder und Muttermörder, den Totschlägern,',
        10: 'Unzüchtigen, Männerbeischläfern, Menschenhändlern, Lügnern, Hochstaplern und was sonst der gesunden Lehre widerspricht,',
        11: 'gemäß der guten Nachricht von der Herrlichkeit des segensreichen Gottes, die mir anvertraut worden ist.',
        12: '‹Ich danke› dem, der mich gestärkt hat – Christus Jesus, unserem Herrn –, weil er mich für treu befunden und in den Dienst gestellt hat,',
        13: 'obwohl ich früher ein Lästerer und Verfolger und Gewalttäter war! Doch ich wurde begnadigt, weil ich unwissend gehandelt hatte, im Unglauben;',
        14: 'und die Gnade unseres Herrn floss über mit der Treue und der Liebe, die in Christus Jesus [sind].',
        15: 'Das Wort [ist] zuverlässig und aller Zustimmung wert: Christus Jesus kam in die Welt, um Sünder zu retten – von denen ich Erster bin.',
        16: 'Doch deshalb wurde ich begnadigt, damit Christus Jesus in mir als Erstem alle Geduld beweist, zum Vorbild derer, die an ihn glauben werden zum ewigen Leben.',
        17: 'Dem König der Ewigkeiten aber, dem unvergänglichen, unsichtbaren, alleinigen Gott [sei] Ehre und Herrlichkeit ‹für immer und ewig›, amen.',
        18: 'Diese Anweisung vertraue ich dir an, [mein] Kind Timotheus, gemäß den zuvor über dich ergangenen Weissagungen, damit du durch sie den guten Kampf kämpfst,',
        19: 'indem du den Glauben und das gute Gewissen behältst, das einige von sich gestoßen und [deshalb] hinsichtlich des Glaubens Schiffbruch erlitten haben;',
        20: 'dazu gehören Hymenäus und Alexander, die ich dem Satan übergeben habe, damit sie unterwiesen werden, nicht in Verruf zu bringen.',
    },
    2: {
        1: 'Ich fordere also vor allem, dass Fürbitten, Gebete, Gesuche, Danksagungen für alle Menschen getan werden,',
        2: 'für Könige und alle, die in verantwortungsvoller Position sind, damit wir ein ruhiges und stilles Leben in aller Ehrfurcht und Ehrbarkeit leben.',
        3: 'Das [ist] gut und genehm vor unserem Retter-Gott,',
        4: 'der will, dass alle Menschen gerettet werden und zur Erkenntnis der Wahrheit kommen.',
        5: 'Denn [es gibt nur] einen Gott, /und [es gibt nur] einen Vermittler zwischen Gott und Menschen, /[nämlich] den Menschen Christus Jesus, /',
        6: 'der sich selbst gegeben hat als Lösegeld für alle, /das Zeugnis zu geeigneter Zeit.',
        7: 'Dazu bin ich als Prediger und Apostel bestimmt worden – ich sage die Wahrheit, ich lüge nicht –, als ein Lehrer der Heiden in Glaube und Wahrheit.',
        8: 'Ich will also, dass die Männer an jedem Ort beten, indem sie heilige Hände aufheben, ohne Zorn und Zweifel.',
        9: 'Genauso auch, dass Frauen sich in ordentlicher Bekleidung, mit Bescheidenheit und Besonnenheit schmücken, nicht mit Haarschmuck und Gold oder Perlen oder teurer Kleidung,',
        10: 'sondern was Frauen ansteht, die sich zur Gottesfurcht bekennen: durch gute Werke.',
        11: 'Eine Frau soll in Stille lernen, in aller Unterordnung;',
        12: 'aber zu lehren gestatte ich einer Frau nicht, auch nicht, über einen Mann zu bestimmen, sondern schweigsam zu sein.',
        13: 'Denn Adam wurde zuerst geformt, danach Eva.',
        14: 'Und Adam ließ sich nicht täuschen, die Frau hingegen ließ sich täuschen und geriet in eine Übertretung;',
        15: 'sie wird aber durch das Kindergebären errettet werden, wenn sie mit Besonnenheit in Glaube und Liebe und Heiligung bleibt!',
    },
    3: {
        1: 'Das Wort [ist] zuverlässig: Wenn jemand die Aufsicht anstrebt, dann begehrt er ein gutes Werk.',
        2: 'Also muss der Aufseher untadelig sein, Ehemann einer einzigen Frau, nüchtern, besonnen, ordentlich, gastfreundlich, belehrbar,',
        3: 'nicht weintrunken, kein Raufbold, sondern nachsichtig, nicht streitsüchtig, nicht geldverliebt,',
        4: '[einer], der dem eigenen Haus in guter Weise vorsteht, der Kinder mit aller Ehrbarkeit in Unterordnung hält',
        5: '(wenn nun jemand dem eigenen Haus nicht vorzustehen weiß, wie sollte er sich um die Gemeinde Gottes kümmern?),',
        6: 'nicht neubekehrt, damit er nicht verblendet in das Gericht des Teufels fällt.',
        7: 'Aber er muss auch einen guten Leumund von denen außerhalb [der Gemeinde] haben, damit er nicht in Ungnade und eine Falle des Teufels gerät.',
        8: 'Genauso [müssen] Diener ehrbar [sein], nicht zweideutig, nicht vielem Wein ergeben, nicht profitgierig,',
        9: '[solche], die das Geheimnis des Glaubens mit einem reinen Gewissen halten.',
        10: 'Und auch sie sollen zuerst geprüft werden, danach sollen sie dienen, wenn sie unbescholten sind.',
        11: 'Genauso [müssen] die Ehefrauen ehrbar [sein], nicht verleumderisch, nüchtern, in allen [Dingen] treu.',
        12: 'Diener sollen Ehemänner einer einzigen Frau sein, Kindern und den eigenen Häusern in guter Weise vorstehen.',
        13: 'Denn die in guter Weise gedient haben, erarbeiten sich einen guten Stand und große Zuversicht im Glauben, der in Christus Jesus [besteht].',
        14: 'Diese [Dinge] schreibe ich dir, obwohl ich hoffe, bald zu dir zu kommen,',
        15: 'aber falls ich mich verspäte, damit du weißt, wie man sich im Haus Gottes verhalten soll, das die Gemeinde des lebendigen Gottes ist, Säule und Stütze der Wahrheit.',
        16: 'Und bekanntermaßen groß ist das Geheimnis der Frömmigkeit: Der sichtbar wurde im Fleisch, / gerechtfertigt wurde im Geist, / gesehen wurde von Engeln, / gepredigt wurde unter Heiden, / geglaubt wurde in der Welt, / aufgenommen wurde in Herrlichkeit.',
    },
    4: {
        1: 'Nun sagt der Geist ausdrücklich, dass in späteren Zeiten einige vom Glauben abfallen werden, weil sie sich trügerischen Geistern und Lehren von Dämonen widmen,',
        2: '[angestachelt] durch die Heuchelei von Lügnern, denen ihr Gewissen gebrandmarkt worden ist,',
        3: 'die verbieten zu heiraten [und verlangen], sich von Speisen fernzuhalten, die Gott zum gemeinsamen Empfang mit Dankbarkeit geschaffen hat für diejenigen, die gläubig [sind] und die Wahrheit erkannt haben.',
        4: 'Denn alle Schöpfung Gottes [ist] gut, und nichts [ist] verwerflich, wenn es mit Dankbarkeit empfangen wird;',
        5: 'denn geheiligt wird es durch das Wort Gottes und Gebet.',
        6: 'Indem du den Geschwistern diese [Dinge] unterbreitest, wirst du ein guter Diener von Christus Jesus sein, geschult in den Worten des Glaubens und der guten Lehre, der du gefolgt bist;',
        7: 'die gottlosen und blödsinnigen Fabeln hingegen lehne ab! Und übe dich in Frömmigkeit!',
        8: 'Denn das körperliche Training ist für Weniges nützlich, aber die Frömmigkeit ist für Alles nützlich, weil sie eine Verheißung des Lebens enthält, des jetzigen und des zukünftigen.',
        9: 'Das Wort [ist] zuverlässig und jeder Zustimmung wert;',
        10: 'denn dafür rackern und kämpfen wir, weil wir [unsere] Hoffnung auf den lebendigen Gott gesetzt haben, der ein Retter aller Menschen ist, insbesondere der Gläubigen.',
        11: 'Gebiete diese [Dinge] und lehre sie!',
        12: 'Niemand soll deine Jugendlichkeit verachten, sondern werde ein Vorbild der Gläubigen im Wort, im Lebenswandel, in Liebe, in Treue, in Reinheit!',
        13: 'Bis ich komme, widme dich dem Lesen, der Ermutigung, dem Lehren!',
        14: 'Vernachlässige nicht die Gnadengabe in dir, die dir durch Weissagung mit Auflegung der Hände der Ältestenschaft gegeben wurde.',
        15: 'Das übe ein! Darin lebe, damit dein Fortschritt für alle sichtbar ist!',
        16: 'Achte auf dich selbst und die Lehre, bleibe in ihnen! Denn indem du das tust, wirst du sowohl dich selbst retten als auch diejenigen, die auf dich hören.',
    },
    5: {
        1: 'Einen älteren [Mann] sollst du nicht tadeln, sondern wie einen Vater ermahnen, jüngere [Männer] wie Brüder,',
        2: 'ältere [Frauen] wie Mütter, jüngere [Frauen] wie Schwestern, in aller Reinheit!',
        3: 'Witwen, die wirklich Witwen [sind], sollst du ehren!',
        4: 'Aber wenn eine Witwe Kinder oder Enkelkinder hat, dann sollen sie zuerst lernen, dem eigenen Haus Ehrfurcht zu erweisen und den Eltern Vergeltungen zurückzugeben; das ist nämlich genehm vor Gott.',
        5: 'Diejenige nun, die wirklich Witwe und auf sich allein gestellt ist, hat auf Gott gehofft und verharrt in den Fürbitten und den Gebeten, bei Nacht und bei Tag;',
        6: 'diejenige aber, die über ihre Verhältnisse lebt, ist tot, obwohl sie lebt.',
        7: 'Und gebiete diese [Dinge], damit sie untadelig seien!',
        8: 'Aber wenn jemand die eigenen [Verwandten] – und besonders die Hausgenossen – nicht versorgt, dann hat er den Glauben verleugnet und ist schlechter als ein Ungläubiger.',
        9: 'Eine Witwe soll registriert werden, wenn sie nicht weniger als sechzig Jahre [alt] ist, Ehefrau eines einzigen Mannes [war],',
        10: 'durch gute Werke bezeugt wird: [sei es], dass sie Kinder aufgezogen hat, dass sie gastfreundlich war, dass sie die Füße der Heiligen gewaschen hat, dass sie Bedrängten geholfen hat, dass sie jedes gute Werk unterstützt hat.',
        11: 'Aber jüngere Witwen weise ab! Denn sobald sie gegen Christus aufbegehren, wollen sie heiraten',
        12: 'und erhalten das Urteil, dass sie den ersten Glauben verworfen haben;',
        13: 'zugleich lernen sie aber auch, untätig [zu sein], weil sie von Haus zu Haus tingeln; und nicht allein untätig, sondern auch geschwätzig und vorwitzig, weil sie reden, was nicht nötig ist.',
        14: 'Ich will also, dass jüngere [Witwen] heiraten, Kinder bekommen, den Haushalt führen, dem Widersacher auch nicht den geringsten Anlass zu übler Nachrede geben.',
        15: 'Denn einige wurden bereits abgelenkt, hinter Satan her.',
        16: 'Wenn eine gläubige [Frau] Witwen [in der Verwandtschaft] hat, dann soll sie ihnen helfen, und die Gemeinde soll nicht belastet werden, damit sie denen hilft, die wirklich Witwen [sind].',
        17: 'Die Ältesten, die [der Gemeinde] gut vorstehen, sollen doppelter Ehre würdig erachtet werden, besonders diejenigen, die sich um Wort und Lehre bemühen!',
        18: 'Denn die Schrift sagt: „Du sollst einem Ochsen, der drischt, das Maul nicht verbinden!“, und: „Der Arbeiter [ist] seinen Lohn wert.“',
        19: 'Gegen einen Ältesten akzeptiere keine Anschuldigung, außer aufgrund von zwei oder drei Zeugen.',
        20: 'Diejenigen, die sündigen, überführe vor allen, damit auch die Übrigen Ehrfurcht haben.',
        21: 'Ich bezeuge vor Gott und Christus Jesus und den auserwählten Engeln, dass du diese [Anweisungen] ohne Vorurteil befolgst und nichts aufgrund einer Begünstigung tust.',
        22: 'Lege niemandem vorschnell die Hände auf, und beteilige dich nicht an fremden Sünden! Halte dich unschuldig!',
        23: 'Trink nicht länger nur Wasser, sondern verwende etwas Wein wegen deines Magens und deiner häufigen Krankheiten.',
        24: 'Die Sünden einiger Leute sind vorab offensichtlich und gehen ihnen voraus zum Gericht, aber einigen folgen sie auch.',
        25: 'Genauso [sind] auch die guten Werke vorab offensichtlich, und diejenigen, bei denen es sich anders verhält, können sich nicht verstecken.',
    },
    6: {
        1: 'Alle, die Sklaven unter einem Joch sind, sollen ihre Hausherren aller Ehre für würdig halten, damit der Name Gottes und die Lehre nicht in Verruf gebracht werden.',
        2: 'Diejenigen hingegen, die gläubige Hausherren haben, sollen [diese] nicht gering achten, weil sie Geschwister sind, sondern sie sollen [ihnen] erst recht dienen, weil die Nutznießer der guten Arbeit gläubige und geliebte [Geschwister] sind. Diese [Dinge] sollst du lehren und einfordern!',
        3: 'Wenn jemand [etwas] anderes lehrt und sich nicht den gesunden Worten unseres Herrn Jesus Christus widmet und der Lehre, die ‹der Frömmigkeit entspricht›,',
        4: 'dann ist er verblendet und glaubt nichts, sondern ist krankhaft [interessiert] an Streitfragen und Wortklaubereien; daraus entstehen Neid, Streit, Lästerungen, böse Verdächtigungen,',
        5: 'endlose Reibereien von Leuten, die den Verstand verloren haben und der Wahrheit beraubt sind, weil sie meinen, die Frömmigkeit sei eine [Möglichkeit zur persönlichen] Bereicherung.',
        6: 'Hingegen ist Frömmigkeit [gepaart] mit Genügsamkeit eine große Bereicherung!',
        7: 'Wir haben nämlich nichts in die Welt hineingebracht, sodass wir auch nichts hinausbringen können;',
        8: 'solange wir nun Nahrung und Kleidung haben, sollten wir uns damit begnügen.',
        9: 'Die aber reich sein wollen, fallen in eine Versuchung und Falle und in viele dumme und abträgliche Begierden, die die Menschen in Ruin und Verderben stürzen.',
        10: 'Denn die Wurzel allen Übels ist die Geldliebe, nach der sich einige ausgestreckt haben und [so] vom Glauben abgeirrt sind und sich selbst mit vielen Qualen durchbohrt haben.',
        11: 'Du aber, oh Mensch Gottes, sollst vor diesen [Dingen] fliehen! Strebe aber nach Gerechtigkeit, Frömmigkeit, Treue, Liebe, Geduld, Sanftmut!',
        12: 'Kämpfe den guten Kampf des Glaubens! Ergreife das ewige Leben, zu dem du berufen wurdest und das gute Bekenntnis bekannt hast vor vielen Zeugen!',
        13: 'Ich gebiete dir vor Gott, der alles lebendig macht, und vor Christus Jesus, der vor Pontius Pilatus das gute Bekenntnis bezeugt hat:',
        14: 'Bewahre du das Gebot fehlerlos [und] untadelig bis zur Erscheinung unseres Herrn Jesus Christus,',
        15: 'die der segensreiche und allein Mächtige zu geeigneter Zeit zeigen wird – der Regent der Regierenden und Herr der Herrschenden,',
        16: 'der allein Unsterblichkeit besitzt und ein unzugängliches Licht bewohnt, den niemand gesehen hat und kein Mensch sehen kann – dem [sei] Ehre und ewige Macht, amen!',
        17: 'Den Reichen in der jetzigen Zeit gebiete, nicht überheblich zu sein und nicht auf ‹unbeständigen Reichtum› zu hoffen, sondern auf Gott, der uns alles reichlich zum Genuss anbietet,',
        18: 'Gutes zu bewirken, reich zu sein in guten Werken, großzügig zu sein, zu teilen bereit,',
        19: 'damit sie für sich selbst eine gute Grundlage für die Zukunft ansparen, sodass sie das wirkliche Leben ergreifen.',
        20: 'Oh Timotheus, bewahre das anvertraute [Gut] und meide die gottlosen Floskeln und die Einwände der sogenannten „Erkenntnis“,',
        21: 'die einige für sich in Anspruch genommen haben und [so] hinsichtlich des Glaubens abgewichen sind. Die Gnade [sei] mit euch!',
    },
}
